statement:
One table records restaurant orders:

- `restaurant_orders(order_id, customer_id, order_timestamp, order_amount, payment_method, order_rating)`: one row per order; `order_id` is unique, `order_timestamp` is a date and time, `payment_method` is `'cash'`, `'card'` or `'app'`, and `order_rating` is 1 to 5, or `null` when the customer did not rate the order.

An order is in **peak hours** when it is placed from 11:00 to 14:00 or from 18:00 to 21:00, that is, when the hour of `order_timestamp` is 11, 12, 13, 18, 19 or 20. No order is placed at exactly 14:00:00 or 21:00:00.

A customer is a **golden hour customer** when all of these hold:

- they placed at least 3 orders;
- at least 60% of their orders are in peak hours;
- they rated at least half of their orders;
- the average of their ratings (ignoring unrated orders), rounded to 2 decimals, is at least 4.0.

For each such customer report `customer_id`, `total_orders` (their number of orders), `peak_hour_percentage` (100 × peak orders / total orders, rounded to a whole number) and `average_rating` (the rounded average). Sort by `average_rating` descending, then by `customer_id` descending.

validator:
function validate(input) {
  const [{ restaurant_orders = [] }] = input;
  const ids = new Set();
  for (const [id, customer, time, amount, method, rating] of restaurant_orders) {
    if ([id, customer, time, amount, method].includes(null)) return 'Only order_rating may be null.';
    if (ids.has(id)) return `order_id ${id} appears twice.`;
    ids.add(id);
    if (!['cash', 'card', 'app'].includes(method)) return `payment_method ${method} must be cash, card or app.`;
    if (rating !== null && !(Number.isInteger(rating) && rating >= 1 && rating <= 5)) return `order_rating ${rating} must be 1 to 5 or null.`;
    if (!/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(time)) return `order_timestamp ${time} must look like 2024-03-01 12:30:00.`;
    if (time.endsWith(' 14:00:00') || time.endsWith(' 21:00:00')) return `order ${id} sits exactly on a peak-hour boundary.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const pad = n => String(n).padStart(2, '0');
  // Small times sit on both sides of every peak boundary; large ones are any minute from 08:00 to 23:59
  // except the two excluded closing instants.
  const clocks = ['10:59:00', '11:00:00', '12:30:00', '13:59:59', '14:30:00', '17:45:00', '18:00:00', '19:15:00', '20:59:00', '21:15:00'];
  const clock = () => {
    if (small) return pick(clocks);
    let h = 8 + Math.floor(rand() * 16), m = Math.floor(rand() * 60);
    if ((h === 14 || h === 21) && m === 0) m = 1;
    return `${pad(h)}:${pad(m)}:00`;
  };
  const ratings = small ? [5, 5, 4, 4, 3, null, null] : [5, 5, 5, 4, 4, 4, 3, 2, 1, null, null, null];
  const restaurant_orders = [];
  // At most 25 orders per customer keeps every percentage and average far from rounding ambiguities.
  const customers = small ? pick([1, 2, 2, 3]) : 160;
  let budget = small ? Math.floor(rand() * 9) : 2000;
  for (let c = 0; c < customers && budget > 0; c++) {
    const customer = small ? 101 + c : 1000 + c;
    const orders = small ? (c === customers - 1 ? budget : Math.min(budget, Math.floor(rand() * 6))) : Math.min(budget, 3 + Math.floor(rand() * 23));
    budget -= orders;
    for (let i = 0; i < orders; i++) {
      const day = `2024-03-${pad(1 + Math.floor(rand() * 28))}`;
      const amount = Math.floor(500 + rand() * 6000) / 100;
      restaurant_orders.push([restaurant_orders.length + 1, customer, `${day} ${clock()}`, amount, pick(['cash', 'card', 'app']), pick(ratings)]);
    }
  }
  return [{ restaurant_orders }];
}
